export interface DeidentifyTemplateConfig {
  /** DeidentifyTemplates contains instructions on how to de-identify content. See https://docs.cloud.google.com/sensitive-data-protection/docs/concepts-templates to learn more. */
  deidentifyTemplate?: DeidentifyTemplate_DeidentifyTemplate | Computed<DeidentifyTemplate_DeidentifyTemplate>;
  /** Deprecated. This field has no effect. */
  locationId?: string | Computed<string>;
  /** The template id can contain uppercase and lowercase letters, numbers, and hyphens; that is, it must match the regular expression: `[a-zA-Z\d-_]+`. The maximum length is 100 characters. Can be empty to allow the system to generate one. */
  templateId?: string | Computed<string>;
}

export interface DeidentifyTemplateAttrs {
  /** Output only. The creation timestamp of an inspectTemplate. */
  createTime: string;
  /** The configuration that controls how the data will change. */
  deidentifyConfig: DeidentifyTemplate_DeidentifyConfig;
  /** DeidentifyTemplates contains instructions on how to de-identify content. See https://docs.cloud.google.com/sensitive-data-protection/docs/concepts-templates to learn more. */
  deidentifyTemplate: DeidentifyTemplate_DeidentifyTemplate;
  /** Short description (max 256 chars). */
  description: string;
  /** Display name (max 256 chars). */
  displayName: string;
  /** Deprecated. This field has no effect. */
  locationId: string;
  /** Output only. The template name. The template will have one of the following formats: `projects/PROJECT_ID/deidentifyTemplates/TEMPLATE_ID` OR `organizations/ORGANIZATION_ID/deidentifyTemplates/TEMPLATE_ID` */
  name: string;
  /** The template id can contain uppercase and lowercase letters, numbers, and hyphens; that is, it must match the regular expression: `[a-zA-Z\d-_]+`. The maximum length is 100 characters. Can be empty to allow the system to generate one. */
  templateId: string;
  /** Output only. The last update timestamp of an inspectTemplate. */
  updateTime: string;
}

